<?php require_once __DIR__.'/includes/ui.php';$c=find_creator((string)($_GET['name']??''));if(!$c){http_response_code(404);head_meta('Không tìm thấy creator','Không tìm thấy');header_ui('creators');empty_content('Không tìm thấy creator');footer_ui();exit;}
$vs=array_values(array_filter(public_videos(),fn($v)=>($v['creator_id']??'')===$c['id']));head_meta($c['name'],'Portfolio video của '.$c['name'],$c['cover']??null);header_ui('creators'); ?>
<div class="profile-cover"><?php if(valid_url($c['cover']??'') && !empty($c['cover'])):?><img class="cover-photo" src="<?=h($c['cover'])?>" alt=""><?php endif;?><div class="profile-cover-label">CREATOR PROFILE / <?=h(strtoupper($c['slug']))?></div></div>
<div class="profile-body"><div class="avatar avatar-xl"><?php if(valid_url($c['avatar']??'')&&!empty($c['avatar'])):?><img src="<?=h($c['avatar'])?>" alt=""><?php else: ?><?=h(strtoupper(substr($c['name'],0,1)))?><?php endif?></div><div class="profile-identity"><span class="section-index">INDEPENDENT CREATOR</span><h1><?=h($c['name'])?></h1><p>@<?=h($c['slug'])?> <span class="dot-sep">·</span> <?=count($vs)?> videos</p><div class="profile-bio"><?=nl2br(h($c['bio']??''))?></div></div><?php if(!empty($c['website']) && valid_url($c['website'])):?><a class="btn btn-outline" target="_blank" rel="noopener noreferrer" href="<?=h($c['website'])?>"><?=icon('globe',17)?> Website <?=icon('arrow-up-right',16)?></a><?php endif;?></div>
<section class="section-block"><div class="section-heading"><div><div class="section-index">VIDEO COLLECTION</div><h2>Tác phẩm <span class="header-dot">.</span></h2></div></div><?php if($vs):?><div class="video-grid"><?php foreach($vs as $v)video_card($v);?></div><?php else:?><?php empty_content('Chưa xuất bản video','Các tác phẩm của creator này sẽ xuất hiện ở đây.');?><?php endif;?></section>
<?php footer_ui();?>
